INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 1, 2, 10001, 1.47, "2023/06/30 12:00:00", "クローチェ", 0.0, "いらっしゃいませっ♪\nキャラバンコインを使って\n買い物ができますよっ！", 2002, 1, "2023/09/22 14:59:59", 1, 126401);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 1, 1, 10002, 2.15, "2023/06/30 12:00:00", "クローチェ", 0.0, "素敵な品が揃ってるので\nたーっくさん買っていって\nくださいねっ♪", 2002, 2, "2023/09/22 14:59:59", 2, 126401);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 1, 2, 10003, 0.0, "2023/06/30 12:00:00", "ライラエル", 0.0, "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", 2002, 2, "2023/09/22 14:59:59", 1, 126501);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 1, 1, 10004, 0.0, "2023/06/30 12:00:00", "ライラエル", 0.0, "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", 2002, 1, "2023/09/22 14:59:59", 2, 126501);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 2, 2, 10005, 0.0, "2023/09/15 15:00:00", "リンド", 0.0, "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", 2002, 2, "2023/12/22 14:59:59", 1, 127702);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 2, 2, 10006, 0.0, "2023/09/15 15:00:00", "リンド", 0.0, "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", 2002, 2, "2023/12/22 14:59:59", 2, 127702);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 2, 1, 10007, 0.0, "2023/09/15 15:00:00", "ヴルム", 0.0, "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", 2002, 1, "2023/12/22 14:59:59", 1, 127802);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 2, 1, 10008, 6.5, "2023/09/15 15:00:00", "ヴルム", 0.0, "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", 2002, 2, "2023/12/22 14:59:59", 2, 127802);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 3, 1, 10009, 0.0, "2023/12/15 15:00:00", "アネモネ", 0.0, "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", 2002, 2, "2024/03/22 14:59:59", 1, 129602);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 3, 1, 10010, 0.0, "2023/12/15 15:00:00", "アネモネ", 0.0, "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", 2002, 2, "2024/03/22 14:59:59", 2, 129602);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 3, 1, 10011, 0.0, "2023/12/15 15:00:00", "ネフィ=ネラ", 0.0, "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", 2002, 1, "2024/03/22 14:59:59", 1, 129701);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 3, 1, 10012, 6.2, "2023/12/15 15:00:00", "ネフィ=ネラ", 0.0, "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", 2002, 2, "2024/03/22 14:59:59", 2, 129701);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 4, 5, 10013, 3.1, "2024/03/15 15:00:00", "カノン", 0.0, "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", 2002, 3, "2024/06/22 14:59:59", 1, 130301);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 4, 2, 10014, 6.15, "2024/03/15 15:00:00", "カノン", 0.0, "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", 2002, 3, "2024/06/22 14:59:59", 2, 130301);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 4, 2, 10015, 0.0, "2024/03/15 15:00:00", "ナーナ", 0.0, "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", 2002, 2, "2024/06/22 14:59:59", 1, 130401);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 4, 1, 10016, 3.35, "2024/03/15 15:00:00", "ナーナ", 0.0, "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", 2002, 2, "2024/06/22 14:59:59", 2, 130401);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 5, 1, 10017, 0.0, "2024/06/15 15:00:00", "ホウオウ", 0.0, "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", 2002, 1, "2024/09/22 14:59:59", 1, 130502);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 5, 1, 10018, 3.18, "2024/06/15 15:00:00", "ホウオウ", 0.0, "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", 2002, 2, "2024/09/22 14:59:59", 2, 130502);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 5, 4, 10019, 0.0, "2024/06/15 15:00:00", "ホウオウ", 0.0, "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", 2002, 4, "2024/09/22 14:59:59", 3, 130503);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 5, 2, 10020, 4.9, "2024/06/15 15:00:00", "ネア", 0.0, "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", 2002, 1, "2024/09/22 14:59:59", 1, 123301);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 5, 2, 10021, 4.8, "2024/06/15 15:00:00", "ネア", 0.0, "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", 2002, 1, "2024/09/22 14:59:59", 2, 123301);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 6, 1, 10022, 4.922, "2024/09/15 15:00:00", "カリザ", 0.0, "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", 2002, 3, "2024/12/22 14:59:59", 1, 133301);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 6, 5, 10023, 9.638, "2024/09/15 15:00:00", "カリザ", 0.0, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", 2002, 3, "2024/12/22 14:59:59", 2, 133301);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 6, 2, 10024, 2.88, "2024/09/15 15:00:00", "ミーア", 0.0, "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", 2002, 1, "2024/12/22 14:59:59", 1, 133401);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 6, 1, 10025, 4.818, "2024/09/15 15:00:00", "ミーア", 0.0, "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", 2002, 5, "2024/12/22 14:59:59", 2, 133401);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 7, 1, 10026, 1.78, "2024/12/15 15:00:00", "グレイス", 0.0, "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", 2002, 2, "2025/03/22 14:59:59", 1, 133002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 7, 7, 10027, 6.15, "2024/12/15 15:00:00", "グレイス", 0.0, "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", 2002, 1, "2025/03/22 14:59:59", 2, 133002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 7, 2, 10028, 4.28, "2024/12/15 15:00:00", "ヴァイオレット", 0.0, "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", 2002, 6, "2025/03/22 14:59:59", 1, 133102);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 7, 1, 10029, 0.0, "2024/12/15 15:00:00", "ヴァイオレット", 0.0, "じめじめした商品は\nございませんので\n安心してお買い求め下さい", 2002, 1, "2025/03/22 14:59:59", 2, 133102);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 8, 1, 10030, 5.53, "2025/03/15 15:00:00", "ルルィ", 0.0, "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", 2002, 2, "2025/06/23 14:59:59", 1, 136902);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 8, 7, 10031, 6.05, "2025/03/15 15:00:00", "ルルィ", 0.0, "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", 2002, 9, "2025/06/23 14:59:59", 2, 136902);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 8, 1, 10032, 0.0, "2025/03/15 15:00:00", "デュラン", 0.0, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", 2002, 2, "2025/06/23 14:59:59", 1, 137001);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 8, 1, 10033, 0.0, "2025/03/15 15:00:00", "デュラン", 0.0, "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", 2002, 2, "2025/06/23 14:59:59", 2, 137001);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 9, 2, 10034, 0.0, "2025/06/16 15:00:00", "サツキ", 0.0, "おう\n好きなもん持ってきな", 2002, 2, "2025/09/23 14:59:59", 1, 135902);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 9, 6, 10035, 4.935, "2025/06/16 15:00:00", "サツキ", 0.0, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", 2002, 1, "2025/09/23 14:59:59", 2, 135902);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 9, 5, 10036, 7.441, "2025/06/16 15:00:00", "ユキノ", 0.0, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", 2002, 2, "2025/09/23 14:59:59", 1, 135802);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 9, 7, 10037, 0.0, "2025/06/16 15:00:00", "ユキノ", 0.0, "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", 2002, 7, "2025/09/23 14:59:59", 2, 135802);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 10, 2, 10038, 2.295, "2025/09/16 15:00:00", "クルル", 0.0, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", 2002, 2, "2025/12/22 14:59:59", 1, 130901);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 10, 6, 10039, 6.281, "2025/09/16 15:00:00", "クルル", 0.0, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", 2002, 1, "2025/12/22 14:59:59", 2, 130901);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 10, 1, 10040, 5.549, "2025/09/16 15:00:00", "ヴォルガーノ", 0.0, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", 2002, 2, "2025/12/22 14:59:59", 1, 137701);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 10, 6, 10041, 2.64, "2025/09/16 15:00:00", "ヴォルガーノ", 0.0, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", 2002, 3, "2025/12/22 14:59:59", 2, 137701);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 11, 4, 10042, 7.642, "2025/12/15 15:00:00", "ライラエル", 0.0, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", 2002, 7, "2026/03/23 11:59:59", 1, 132801);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 11, 1, 10043, 0.0, "2025/12/15 15:00:00", "ライラエル", 0.0, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", 2002, 1, "2026/03/23 11:59:59", 2, 132802);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 11, 1, 10044, 0.0, "2025/12/15 15:00:00", "クローチェ", 0.0, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", 2002, 1, "2026/03/23 11:59:59", 1, 134502);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 11, 1, 10045, 3.72, "2025/12/15 15:00:00", "クローチェ", 0.0, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", 2002, 2, "2026/03/23 11:59:59", 2, 134501);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 12, 1, 10046, 4.991, "2026/03/16 12:00:00", "ネフィ＝ネラ", 0.0, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", 2002, 2, "2026/06/22 11:59:59", 1, 138201);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 12, 4, 10047, 3.877, "2026/03/16 12:00:00", "ネフィ＝ネラ", 0.0, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", 2002, 1, "2026/06/22 11:59:59", 2, 138201);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 12, 6, 10048, 1.71, "2026/03/16 12:00:00", "アラクネ", 0.0, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", 2002, 4, "2026/06/22 11:59:59", 1, 136001);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 12, 2, 10049, 5.32, "2026/03/16 12:00:00", "アラクネ", 0.0, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", 2002, 5, "2026/06/22 11:59:59", 2, 136001);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 13, 4, 10050, 3.727, "2026/06/15 12:00:00", "アネモネ", 0.0, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", 2002, 9, "2026/09/22 11:59:59", 1, 135401);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 13, 9, 10051, 7.213, "2026/06/15 12:00:00", "アネモネ", 0.0, "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", 2002, 7, "2026/09/22 11:59:59", 2, 135401);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 13, 2, 10052, 1.874, "2026/06/15 12:00:00", "クリア", 0.0, "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", 2002, 1, "2026/09/22 11:59:59", 1, 135301);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 13, 2, 10053, 0.0, "2026/06/15 12:00:00", "クリア", 0.0, "アルバイトが終わったら\n海に遊びに行きましょう！\nモネちゃんも一緒に♪", 2002, 2, "2026/09/22 11:59:59", 2, 135301);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 14, 1, 10054, 4.215, "2026/09/15 12:00:00", "ヴァイオレット", 0.0, "大いなる命、神なる勇魚…\n慈しみの矜持を胸に素敵な\n商品をお売りいたします", 2002, 2, "2026/12/22 11:59:59", 1, 138001);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 14, 4, 10055, 0.0, "2026/09/15 12:00:00", "ヴァイオレット", 0.0, "すみません、わたくしの\n手料理は売り切れなのです\nグレイスが、買い占めを…", 2002, 4, "2026/12/22 11:59:59", 2, 138001);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 14, 1, 10056, 5.477, "2026/09/15 12:00:00", "グレイス", 0.0, "何故かいかがわしいお店と\n勘違いされるんですよね\n騎士氏も？　ヤダへんふし", 2002, 6, "2026/12/22 11:59:59", 1, 138901);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (-470.0, 14, 1, 10057, 5.743, "2026/09/15 12:00:00", "グレイス", 0.0, "どうも。グレイスちゃん\n客寄せバージョンですぴょん\n一名様ごあんな～い", 2002, 2, "2026/12/22 11:59:59", 2, 138901);
